-- Banco de preguntas tipo Saber 11 del colegio: 40 preguntas originales (8 por área).
-- Idempotente: cada pregunta tiene id fijo y no se vuelve a insertar. Requiere la migración BancoPreguntas.
INSERT INTO colegio.preguntas_banco (id, area, competencia, contexto, enunciado, opciones, correcta, explicacion, grados, dificultad, creado_en)
SELECT v.id::uuid, v.area, v.competencia, v.contexto, v.enunciado, v.opciones, v.correcta, v.explicacion, v.grados, v.dificultad, now()
FROM (VALUES
    ('f8d70f9b-45b9-57c5-a0c0-23dfd850bcc7', 'LecturaCritica', 'Comprender cómo se articulan las partes de un texto', 'En muchas ciudades costeras, el crecimiento urbano ha avanzado sobre manglares y ciénagas. Quienes defienden esta expansión sostienen que la vivienda es una necesidad urgente y que los terrenos inundables, una vez rellenados, permiten construir barrios enteros a bajo costo. Sin embargo, los manglares no son terrenos vacíos: protegen la costa del oleaje, sirven de criadero a peces que alimentan a comunidades de pescadores y absorben grandes cantidades de carbono. Rellenarlos puede resolver un problema inmediato, pero traslada a las próximas generaciones el costo de inundaciones más frecuentes y de una pesca cada vez más escasa. Por eso, la discusión no debería plantearse como vivienda contra naturaleza, sino como una pregunta sobre dónde y cómo construir sin destruir aquello que también nos protege.', '¿Cuál es la tesis que defiende el autor?', ARRAY['La construcción de vivienda debe detenerse en las ciudades costeras.', 'Los manglares deben conservarse aunque eso impida resolver la falta de vivienda.', 'El problema de vivienda debe resolverse sin destruir los ecosistemas que protegen a la ciudad.', 'Rellenar las ciénagas es la forma más económica de construir barrios.']::text[], 2, 'El último enunciado plantea la idea central: no es vivienda contra naturaleza, sino dónde y cómo construir sin destruir lo que protege.', ARRAY[10, 11]::integer[], 'Media'),
    ('0028b846-894b-52eb-ac3f-52437875aed9', 'LecturaCritica', 'Comprender cómo se articulan las partes de un texto', 'En muchas ciudades costeras, el crecimiento urbano ha avanzado sobre manglares y ciénagas. Quienes defienden esta expansión sostienen que la vivienda es una necesidad urgente y que los terrenos inundables, una vez rellenados, permiten construir barrios enteros a bajo costo. Sin embargo, los manglares no son terrenos vacíos: protegen la costa del oleaje, sirven de criadero a peces que alimentan a comunidades de pescadores y absorben grandes cantidades de carbono. Rellenarlos puede resolver un problema inmediato, pero traslada a las próximas generaciones el costo de inundaciones más frecuentes y de una pesca cada vez más escasa. Por eso, la discusión no debería plantearse como vivienda contra naturaleza, sino como una pregunta sobre dónde y cómo construir sin destruir aquello que también nos protege.', 'En el texto, la expresión «los manglares no son terrenos vacíos» se usa para', ARRAY['describir el paisaje de las ciudades costeras.', 'refutar la idea de que rellenarlos no tiene costos.', 'explicar cómo se construyen barrios sobre las ciénagas.', 'mostrar que los manglares ya están habitados por personas.']::text[], 1, 'Introduce, con «Sin embargo», las funciones de los manglares que contradicen el argumento de quienes los rellenan.', ARRAY[10, 11]::integer[], 'Media'),
    ('f40a6afd-32af-5bd5-9074-78bea03c0254', 'LecturaCritica', 'Reflexionar a partir de un texto y evaluar su contenido', 'En muchas ciudades costeras, el crecimiento urbano ha avanzado sobre manglares y ciénagas. Quienes defienden esta expansión sostienen que la vivienda es una necesidad urgente y que los terrenos inundables, una vez rellenados, permiten construir barrios enteros a bajo costo. Sin embargo, los manglares no son terrenos vacíos: protegen la costa del oleaje, sirven de criadero a peces que alimentan a comunidades de pescadores y absorben grandes cantidades de carbono. Rellenarlos puede resolver un problema inmediato, pero traslada a las próximas generaciones el costo de inundaciones más frecuentes y de una pesca cada vez más escasa. Por eso, la discusión no debería plantearse como vivienda contra naturaleza, sino como una pregunta sobre dónde y cómo construir sin destruir aquello que también nos protege.', '¿Cuál de los siguientes enunciados, de ser cierto, DEBILITARÍA el argumento del autor?', ARRAY['Las comunidades de pescadores dependen de los peces que se crían en los manglares.', 'Las inundaciones aumentaron en barrios construidos sobre ciénagas rellenadas.', 'Un estudio demuestra que los manglares rellenados se recuperan solos en pocos años sin perder sus funciones.', 'La demanda de vivienda en las ciudades costeras sigue creciendo.']::text[], 2, 'Si los manglares se recuperaran solos, desaparecería el costo futuro en que se apoya el autor. Las opciones A y B lo refuerzan.', ARRAY[10, 11]::integer[], 'Alta'),
    ('5b1d60b0-dd22-53b9-b258-48741ab681b3', 'LecturaCritica', 'Identificar y entender los contenidos locales', 'En muchas ciudades costeras, el crecimiento urbano ha avanzado sobre manglares y ciénagas. Quienes defienden esta expansión sostienen que la vivienda es una necesidad urgente y que los terrenos inundables, una vez rellenados, permiten construir barrios enteros a bajo costo. Sin embargo, los manglares no son terrenos vacíos: protegen la costa del oleaje, sirven de criadero a peces que alimentan a comunidades de pescadores y absorben grandes cantidades de carbono. Rellenarlos puede resolver un problema inmediato, pero traslada a las próximas generaciones el costo de inundaciones más frecuentes y de una pesca cada vez más escasa. Por eso, la discusión no debería plantearse como vivienda contra naturaleza, sino como una pregunta sobre dónde y cómo construir sin destruir aquello que también nos protege.', 'Según el texto, quienes defienden la expansión urbana sobre las ciénagas argumentan que', ARRAY['la vivienda es una necesidad urgente y esos terrenos permiten construir a bajo costo.', 'los manglares absorben carbono y protegen la costa del oleaje.', 'la pesca será más abundante si se rellenan las ciénagas.', 'las próximas generaciones pagarán el costo de las inundaciones.']::text[], 0, 'Lo dice la segunda oración del texto.', ARRAY[10, 11]::integer[], 'Baja'),
    ('8e55c58d-3706-5223-951a-94d679dd687e', 'LecturaCritica', 'Identificar y entender los contenidos locales', 'Cuando la abuela dejó de recordar nuestros nombres, empezó a recordar canciones. Las cantaba despacio, mientras desgranaba maíz en el patio, como si cada grano fuera una sílaba que se le hubiera perdido hacía mucho tiempo. Mi madre lloraba en la cocina; yo, que tenía diez años, me sentaba a su lado y aprendía las letras. Ahora que ella ya no está, soy yo quien canta en el patio, y a veces siento que no recuerdo las canciones: son ellas las que me recuerdan a mí.', 'En el fragmento, comparar cada grano de maíz con «una sílaba que se le hubiera perdido» sugiere que la abuela', ARRAY['trabajaba con prisa para terminar antes de olvidar.', 'recuperaba con las canciones algo de la memoria que estaba perdiendo.', 'le enseñaba al narrador a leer mientras desgranaba.', 'cantaba canciones que había inventado ese mismo día.']::text[], 1, 'La comparación une el gesto de desgranar con recobrar, sílaba a sílaba, lo que se había olvidado.', ARRAY[10, 11]::integer[], 'Media'),
    ('c7484de4-9723-50d5-9137-85161bd664b4', 'LecturaCritica', 'Reflexionar a partir de un texto y evaluar su contenido', 'Cuando la abuela dejó de recordar nuestros nombres, empezó a recordar canciones. Las cantaba despacio, mientras desgranaba maíz en el patio, como si cada grano fuera una sílaba que se le hubiera perdido hacía mucho tiempo. Mi madre lloraba en la cocina; yo, que tenía diez años, me sentaba a su lado y aprendía las letras. Ahora que ella ya no está, soy yo quien canta en el patio, y a veces siento que no recuerdo las canciones: son ellas las que me recuerdan a mí.', 'La frase final «son ellas las que me recuerdan a mí» significa que, para el narrador, las canciones', ARRAY['son difíciles de memorizar.', 'le recuerdan que debe cuidar a su madre.', 'mantienen viva su propia identidad y su vínculo con la abuela.', 'le ayudan a olvidar la tristeza de la cocina.']::text[], 2, 'Invierte la relación: no es él quien conserva las canciones, sino ellas las que conservan quién es él y de dónde viene.', ARRAY[10, 11]::integer[], 'Alta'),
    ('7e5f2c73-bbb4-58bc-9be2-ff2581fa822a', 'LecturaCritica', 'Reflexionar a partir de un texto y evaluar su contenido', 'Resultados de una encuesta a 400 estudiantes de grado 11 de un municipio:
- El 62 % usa el celular más de 5 horas al día. De ellos, el 48 % duerme menos de 6 horas.
- Entre quienes usan el celular menos de 2 horas al día, el 15 % duerme menos de 6 horas.', '¿Qué conclusión se puede extraer de la información?', ARRAY['El uso del celular causa insomnio en todos los estudiantes.', 'Entre los encuestados, dormir poco es más frecuente en quienes usan más el celular.', 'La mayoría de los estudiantes del país duerme menos de 6 horas.', 'Los estudiantes que usan menos el celular obtienen mejores notas.']::text[], 1, '48 % frente a 15 %: es una comparación dentro de la muestra. No habla de causas, del país ni de notas.', ARRAY[10, 11]::integer[], 'Media'),
    ('5a98e10a-8e9e-514f-8a2c-610cf74abc52', 'LecturaCritica', 'Reflexionar a partir de un texto y evaluar su contenido', 'Resultados de una encuesta a 400 estudiantes de grado 11 de un municipio:
- El 62 % usa el celular más de 5 horas al día. De ellos, el 48 % duerme menos de 6 horas.
- Entre quienes usan el celular menos de 2 horas al día, el 15 % duerme menos de 6 horas.', 'Un estudiante afirma: «Está demostrado que el celular quita el sueño». Esta afirmación es problemática porque', ARRAY['la encuesta no preguntó cuántas horas duermen los estudiantes.', 'la encuesta muestra una relación entre los datos, pero no prueba que una cosa cause la otra.', 'el porcentaje de estudiantes que usa el celular es muy bajo.', 'los datos solo incluyen a estudiantes que no usan celular.']::text[], 1, 'Una correlación no demuestra causalidad: podría haber otras causas (horarios, trabajo, estrés).', ARRAY[10, 11]::integer[], 'Alta'),
    ('dde42a26-cea6-5752-871c-fcf3175ee2b5', 'Matematicas', 'Formulación y ejecución', NULL, 'Una tienda ofrece 20 % de descuento sobre un pantalón de $80.000 y luego cobra IVA del 19 % sobre el precio con descuento. ¿Cuánto paga el cliente?', ARRAY['$76.160', '$79.200', '$64.000', '$75.200']::text[], 0, '80.000 × 0,80 = 64.000; 64.000 × 1,19 = 76.160.', ARRAY[10, 11]::integer[], 'Media'),
    ('ffb4df12-16a3-5e9b-952b-1fb13399f9d0', 'Matematicas', 'Formulación y ejecución', NULL, 'El promedio de 4 notas de un estudiante es 3,5. ¿Qué nota necesita en la quinta para que el promedio de las 5 sea 3,8?', ARRAY['4,0', '4,5', '5,0', '3,8']::text[], 2, 'Necesita sumar 3,8 × 5 = 19; ya tiene 3,5 × 4 = 14; le faltan 5,0.', ARRAY[10, 11]::integer[], 'Media'),
    ('68fd7df5-9aed-5abd-8274-080606ef0c02', 'Matematicas', 'Interpretación y representación', 'Un operador ofrece dos planes de datos mensuales:
- Plan A: $30.000 que incluyen 5 GB, y $2.000 por cada GB adicional.
- Plan B: $45.000 con datos ilimitados.', '¿A partir de cuántos GB consumidos al mes resulta más barato el plan B?', ARRAY['8 GB', '10 GB', '13 GB', '15 GB']::text[], 2, 'Con 12 GB el plan A cuesta 30.000 + 7 × 2.000 = 44.000; con 13 GB cuesta 46.000, más que el plan B.', ARRAY[10, 11]::integer[], 'Alta'),
    ('cc4c9db5-09d3-599a-9b81-009604729429', 'Matematicas', 'Formulación y ejecución', NULL, 'Una piscina rectangular mide 10 m de largo, 5 m de ancho y 1,5 m de profundidad. ¿Cuántos litros de agua se necesitan para llenarla? (1 m³ = 1.000 litros)', ARRAY['7.500', '75.000', '750.000', '750']::text[], 1, 'Volumen = 10 × 5 × 1,5 = 75 m³ = 75.000 litros.', ARRAY[10, 11]::integer[], 'Baja'),
    ('4770fb95-d704-5267-8a72-a282ffb76bcb', 'Matematicas', 'Interpretación y representación', NULL, 'En una urna hay 3 balotas rojas, 5 azules y 2 verdes. Si se saca una balota al azar, ¿cuál es la probabilidad de que NO sea azul?', ARRAY['1/5', '3/10', '1/2', '7/10']::text[], 2, 'Hay 5 balotas que no son azules de 10 en total: 5/10 = 1/2.', ARRAY[10, 11]::integer[], 'Baja'),
    ('342e5001-e4fc-5569-ad16-faa1aaaffa7a', 'Matematicas', 'Argumentación', NULL, 'Un estudiante afirma que si se duplica el lado de un cuadrado, su área también se duplica. ¿Es correcta la afirmación?', ARRAY['Sí, porque el área es proporcional al lado.', 'Sí, porque al duplicar cualquier medida se duplican todas las demás.', 'No, porque el área se multiplica por 4.', 'No, porque el área se multiplica por 8.']::text[], 2, 'Área = l². Con lado 2l, el área es (2l)² = 4l².', ARRAY[10, 11]::integer[], 'Media'),
    ('ed810508-3679-5412-ba19-2fbfcc4fda80', 'Matematicas', 'Interpretación y representación', NULL, 'Un taxi cobra $4.500 de banderazo más $900 por cada kilómetro recorrido. ¿Qué expresión da el costo C de un viaje de x kilómetros?', ARRAY['C = 4.500 + 900x', 'C = 900 + 4.500x', 'C = 5.400x', 'C = 4.500x + 900']::text[], 0, 'El banderazo es fijo y a él se suman 900 pesos por cada kilómetro.', ARRAY[10, 11]::integer[], 'Baja'),
    ('077bee75-630f-5a65-8533-24ca58f05c69', 'Matematicas', 'Argumentación', NULL, 'Las edades de cinco estudiantes son 16, 17, 17, 18 y 22 años. ¿Cuál afirmación es verdadera?', ARRAY['La media es 17 años.', 'La mediana es 17 años y la media es 18 años.', 'La moda es 18 años.', 'La media y la mediana son iguales.']::text[], 1, 'Media = 90 / 5 = 18; mediana (dato central) = 17; moda = 17.', ARRAY[10, 11]::integer[], 'Media'),
    ('1f7130ec-4b6b-5615-88b0-5717e89e0786', 'SocialesCiudadanas', 'Pensamiento social', NULL, 'Según la Constitución de 1991, ¿qué mecanismo puede usar una persona para pedir a un juez la protección inmediata de sus derechos fundamentales?', ARRAY['La acción de tutela.', 'La acción popular.', 'El referendo.', 'La revocatoria del mandato.']::text[], 0, 'La tutela (artículo 86) protege de forma inmediata los derechos fundamentales.', ARRAY[10, 11]::integer[], 'Baja'),
    ('2c483f72-06c5-5d1b-8563-457b1fbb1a00', 'SocialesCiudadanas', 'Interpretación y análisis de perspectivas', NULL, 'Un concejo municipal prohíbe a un grupo religioso reunirse en los parques públicos, mientras otros grupos sí pueden hacerlo. Esta decisión vulnera principalmente', ARRAY['el derecho a la propiedad privada.', 'la libertad de cultos y el derecho a la igualdad.', 'el derecho al trabajo.', 'la libre competencia económica.']::text[], 1, 'Trata distinto a un grupo por su religión: afecta la libertad de cultos (art. 19) y la igualdad (art. 13).', ARRAY[10, 11]::integer[], 'Media'),
    ('5b2c0105-4bc0-5849-aa3d-9bc86bc5e388', 'SocialesCiudadanas', 'Pensamiento reflexivo y sistémico', 'Una empresa quiere construir una represa en un río. Los campesinos temen perder sus tierras, el alcalde espera nuevos empleos y un grupo ambientalista advierte que se afectarán los peces del río.', '¿Cuál de las siguientes propuestas tiene en cuenta los intereses de todos los actores?', ARRAY['Construir la represa de inmediato, porque generará empleo.', 'Prohibir el proyecto, porque afecta al medio ambiente.', 'Realizar estudios de impacto, consultar a las comunidades y acordar compensaciones antes de decidir.', 'Dejar que la empresa decida, porque es la que invierte el dinero.']::text[], 2, 'Es la única opción que considera a la vez empleo, tierras y ambiente.', ARRAY[10, 11]::integer[], 'Media'),
    ('c95af51d-1d18-50c2-af53-ec4e5991f64b', 'SocialesCiudadanas', 'Pensamiento social', NULL, 'En Colombia, ¿qué rama del poder público tiene como función principal hacer las leyes?', ARRAY['La rama ejecutiva, encabezada por el presidente.', 'La rama legislativa, a través del Congreso.', 'La rama judicial, a través de la Corte Constitucional.', 'La organización electoral, a través de la Registraduría.']::text[], 1, 'El Congreso (Senado y Cámara) hace las leyes.', ARRAY[10, 11]::integer[], 'Baja'),
    ('f4f638d7-4a18-5370-85b0-1223c0b0779c', 'SocialesCiudadanas', 'Pensamiento social', NULL, 'El Frente Nacional (1958-1974) fue un acuerdo mediante el cual', ARRAY['los partidos Liberal y Conservador se alternaron la presidencia y se repartieron los cargos públicos.', 'Colombia se unió con Venezuela y Ecuador en una sola república.', 'se firmó la paz con todas las guerrillas del país.', 'se aprobó la Constitución de 1991.']::text[], 0, 'Tras la violencia bipartidista, liberales y conservadores pactaron alternarse el poder durante 16 años.', ARRAY[10, 11]::integer[], 'Media'),
    ('187f92cf-33ca-5e6b-80c0-375d3612ded1', 'SocialesCiudadanas', 'Pensamiento reflexivo y sistémico', NULL, 'Si el Banco de la República sube la tasa de interés, lo más probable es que', ARRAY['los créditos se abaraten y aumente el consumo.', 'los créditos se encarezcan y el consumo tienda a disminuir.', 'el gobierno deba subir los impuestos.', 'los salarios aumenten automáticamente.']::text[], 1, 'Una tasa más alta hace más costoso endeudarse, lo que frena el gasto; así se controla la inflación.', ARRAY[10, 11]::integer[], 'Alta'),
    ('359500a1-0f8b-5eb1-9730-c0196382fb86', 'SocialesCiudadanas', 'Pensamiento social', NULL, '¿A qué región natural de Colombia pertenece Cartagena de Indias?', ARRAY['Región Andina.', 'Región Pacífica.', 'Región Caribe.', 'Orinoquía.']::text[], 2, 'Cartagena está en la costa del mar Caribe.', ARRAY[10, 11]::integer[], 'Baja'),
    ('e2bee8f0-f33f-5911-a035-a8f60153168c', 'SocialesCiudadanas', 'Interpretación y análisis de perspectivas', NULL, 'En el gobierno escolar, la función principal del personero o personera estudiantil es', ARRAY['promover y defender los derechos y deberes de los estudiantes.', 'administrar el presupuesto del colegio.', 'elegir a los docentes de cada curso.', 'aprobar el Proyecto Educativo Institucional.']::text[], 0, 'Así lo establece el Decreto 1860 de 1994 (hoy compilado en el Decreto 1075 de 2015).', ARRAY[10, 11]::integer[], 'Baja'),
    ('eb336c06-3012-5c2b-bfb2-0ccded3f2532', 'CienciasNaturales', 'Uso comprensivo del conocimiento científico', NULL, 'Se deja caer un objeto desde el reposo. Si se desprecia la resistencia del aire y la gravedad es 10 m/s², ¿qué velocidad tiene a los 2 segundos?', ARRAY['5 m/s', '10 m/s', '20 m/s', '40 m/s']::text[], 2, 'v = g × t = 10 × 2 = 20 m/s.', ARRAY[10, 11]::integer[], 'Baja'),
    ('973e92f0-15e8-5bfc-9efe-6d9a8096af9c', 'CienciasNaturales', 'Uso comprensivo del conocimiento científico', NULL, 'Durante la fotosíntesis, las plantas toman dióxido de carbono y agua y liberan a la atmósfera', ARRAY['oxígeno.', 'nitrógeno.', 'metano.', 'dióxido de azufre.']::text[], 0, '6 CO₂ + 6 H₂O + luz → C₆H₁₂O₆ + 6 O₂.', ARRAY[10, 11]::integer[], 'Baja'),
    ('021ce48b-146b-52ad-9a54-6603cccacdd7', 'CienciasNaturales', 'Explicación de fenómenos', NULL, 'Al mezclar vinagre con bicarbonato de sodio se forman muchas burbujas. Esto ocurre porque', ARRAY['el vinagre se evapora al tocar el bicarbonato.', 'se produce una reacción química que libera dióxido de carbono.', 'el bicarbonato se disuelve sin reaccionar.', 'el agua del vinagre cambia de estado líquido a gaseoso.']::text[], 1, 'El ácido acético reacciona con el bicarbonato y produce CO₂, agua y acetato de sodio.', ARRAY[10, 11]::integer[], 'Media'),
    ('7f9d9092-8949-51fc-90c3-e0bc17b8e033', 'CienciasNaturales', 'Indagación', NULL, 'Una estudiante quiere saber si la luz afecta el crecimiento de plantas de fríjol. Siembra dos grupos con el mismo suelo y la misma agua; pone uno al sol y otro en un cuarto oscuro. ¿Cuál es la variable independiente del experimento?', ARRAY['La altura de las plantas.', 'La cantidad de luz que recibe cada grupo.', 'El tipo de suelo.', 'La cantidad de agua.']::text[], 1, 'Es lo que la estudiante cambia a propósito; la altura es lo que mide (variable dependiente).', ARRAY[10, 11]::integer[], 'Media'),
    ('3a0418b5-180f-52e0-9c6a-ff69248441e5', 'CienciasNaturales', 'Explicación de fenómenos', NULL, 'Si dos padres heterocigotos (Aa) para un rasgo con dominancia completa tienen un hijo, ¿cuál es la probabilidad de que el hijo presente el rasgo recesivo (aa)?', ARRAY['0 %', '25 %', '50 %', '75 %']::text[], 1, 'En el cuadro de Punnett Aa × Aa: AA, Aa, Aa, aa. Uno de cuatro es aa.', ARRAY[10, 11]::integer[], 'Media'),
    ('e6bbbd76-500c-57cf-94ab-f8316a4d3f8a', 'CienciasNaturales', 'Explicación de fenómenos', 'En un ecosistema existe la cadena alimentaria: pasto → saltamontes → rana → serpiente.', 'Si desaparecen las ranas, lo más probable en un primer momento es que', ARRAY['aumenten los saltamontes y disminuyan las serpientes.', 'aumenten las serpientes y los saltamontes.', 'disminuyan los saltamontes y aumente el pasto.', 'no cambie ninguna población.']::text[], 0, 'Los saltamontes pierden a su depredador y las serpientes se quedan sin alimento.', ARRAY[10, 11]::integer[], 'Media'),
    ('31be60bc-3e0e-5880-8e90-c2ae7e3f6a35', 'CienciasNaturales', 'Uso comprensivo del conocimiento científico', NULL, 'En un circuito eléctrico se duplica el voltaje y la resistencia se mantiene igual. Según la ley de Ohm, la corriente', ARRAY['se reduce a la mitad.', 'no cambia.', 'se duplica.', 'se cuadruplica.']::text[], 2, 'I = V / R: si V se duplica y R no cambia, I se duplica.', ARRAY[10, 11]::integer[], 'Media'),
    ('42e5ea62-9343-5e59-8d5a-6446954c8038', 'CienciasNaturales', 'Uso comprensivo del conocimiento científico', NULL, 'Una solución tiene pH 3. Esta solución es', ARRAY['ácida.', 'básica.', 'neutra.', 'imposible de clasificar sin conocer su color.']::text[], 0, 'pH menor que 7 es ácido; 7 es neutro; mayor que 7 es básico.', ARRAY[10, 11]::integer[], 'Baja'),
    ('a7b682d6-95c7-5217-8798-fa40886014ee', 'Ingles', 'Parte 1: avisos', NULL, 'Where can you see this notice?

«PLEASE KEEP YOUR VOICE DOWN. STUDENTS ARE READING.»', ARRAY['In a school library.', 'At a football stadium.', 'In a swimming pool.']::text[], 0, 'Pide silencio porque hay estudiantes leyendo: es un aviso de biblioteca.', ARRAY[10, 11]::integer[], 'Baja'),
    ('48bdbc06-76af-5879-887c-60111b383449', 'Ingles', 'Parte 1: avisos', NULL, 'What does this notice mean?

«NO PARKING – EMERGENCY EXIT»', ARRAY['You can park here only in an emergency.', 'Do not leave your car here because people may need to get out.', 'Emergency vehicles cannot use this exit.']::text[], 1, 'La salida de emergencia debe quedar libre.', ARRAY[10, 11]::integer[], 'Media'),
    ('ae8848e8-7cdb-5ac6-b43b-aef2ecacadec', 'Ingles', 'Parte 2: vocabulario', NULL, 'Which word matches the description?

«You use this to protect yourself from the rain.»', ARRAY['umbrella', 'scarf', 'wallet', 'ticket']::text[], 0, 'Umbrella = paraguas.', ARRAY[10, 11]::integer[], 'Baja'),
    ('e86fc9fc-1fe3-504d-8249-78df233b3b0b', 'Ingles', 'Parte 3: conversaciones', NULL, 'Complete the conversation.

— Would you like some more juice?
